//! Reading the hand-authored fixtures (task P2-08) into the model.
//!
//! The fixtures are generated by [`common::build`], our own minimal Visio
//! packages (ADR 0016): a drawing, a stencil and a template, plus one broken
//! package per failure mode. Reading them exercises the mapping rules of
//! `larrygram_vsdx::to_model` without the corpus.

mod common;

use larrygram_model::{DocumentKind, StyleId};
use larrygram_vsdx::{Limits, read_document, read_package, to_model};

use crate::common::{Fixture, Malformed};

/// Reads a fixture through the bytes of a file.
fn read_fixture(fixture: Fixture) -> Result<larrygram_model::Document, larrygram_vsdx::Error> {
    let bytes = common::build(fixture);
    read_document(&bytes, &Limits::DEFAULT)
}

#[test]
fn minimal_drawing_reads() {
    let document = read_fixture(Fixture::Drawing).expect("fixture reads");
    assert_eq!(document.kind, DocumentKind::Drawing);
    assert_eq!(document.pages.len(), 1);
    assert_eq!(document.masters.len(), 0);

    let page = &document.pages[0];
    assert_eq!(page.visio_id, 0);
    assert_eq!(page.name, "Page-1");
    assert_eq!(page.name_u, "Page-1");
    assert_eq!(page.background, None);
    assert_eq!(page.sheet.cells.len(), 2);
    assert_eq!(page.sheet.cells[0].name.as_str(), "PageWidth");
    assert_eq!(page.shapes.len(), 1);

    let shape = document.shape(page.shapes[0]).expect("shape");
    assert_eq!(shape.visio_id, 1);
    assert_eq!(shape.master, None);
    assert_eq!(shape.sheet.cells.len(), 6);
    assert_eq!(shape.sheet.cells[0].name.as_str(), "PinX");
    assert_eq!(
        shape.sheet.cells[0].value,
        Some(larrygram_model::CellValue::Number(2.0))
    );
    assert_eq!(shape.sheet.sections.len(), 1);
    let geometry = &shape.sheet.sections[0];
    assert_eq!(geometry.name.as_str(), "Geometry");
    assert_eq!(geometry.rows.len(), 5);
    assert_eq!(geometry.rows[0].row_type.as_deref(), Some("RelMoveTo"));
    assert_eq!(geometry.rows[0].ix, Some(1));
    // The section-level `NoFill` cell maps to `Section::cells` (P2-06b).
    assert_eq!(geometry.cells.len(), 1);
    assert_eq!(geometry.cells[0].name.as_str(), "NoFill");
    assert!(geometry.preserved.children.is_empty());
}

#[test]
fn minimal_stencil_reads_with_the_stencil_kind() {
    let document = read_fixture(Fixture::Stencil).expect("fixture reads");
    assert_eq!(document.kind, DocumentKind::Stencil);
    // A stencil has no drawing pages (ADR 0016).
    assert_eq!(document.pages.len(), 0);
    assert_eq!(document.masters.len(), 1);

    let master = &document.masters[0];
    assert_eq!(master.visio_id, 1);
    assert_eq!(master.name, "Master 1");
    assert_eq!(master.name_u, "Master.1");
    assert_eq!(
        master.unique_id.as_deref(),
        Some("{5A4E1C2D-3B6F-4A21-9C0D-8E7F6A5B4C3D}")
    );
    assert!(!master.hidden);
    let shape = document
        .shape(master.shapes.first().copied().expect("master shape"))
        .expect("shape");
    assert_eq!(shape.sheet.cells.len(), 6);
}

#[test]
fn minimal_template_reads_with_the_template_kind() {
    let document = read_fixture(Fixture::Template).expect("fixture reads");
    assert_eq!(document.kind, DocumentKind::Template);
    assert_eq!(document.pages.len(), 1);
    assert_eq!(document.masters.len(), 1);
}

#[test]
fn the_style_sheet_maps_to_styles() {
    // The fixtures have no `StyleSheets` element; a document without one has
    // an empty stylesheet.
    let document = read_fixture(Fixture::Drawing).expect("fixture reads");
    assert_eq!(document.stylesheet.styles.len(), 0);
    assert_eq!(document.style(StyleId { index: 0 }), None);
}

#[test]
fn a_missing_main_part_is_an_error() {
    let bytes = common::build(Fixture::Malformed(Malformed::MissingMainPart));
    assert!(matches!(
        read_document(&bytes, &Limits::DEFAULT),
        Err(larrygram_vsdx::Error::MissingPart(_))
    ));
}

#[test]
fn a_package_without_content_types_reads_as_a_drawing() {
    // Two corpus files have no `[Content_Types].xml` (task P2-05); the main
    // part is found through the package root relationship and the kind
    // defaults to `Drawing`.
    let bytes = common::build(Fixture::Malformed(Malformed::NoContentTypes));
    let document = read_document(&bytes, &Limits::DEFAULT).expect("reads");
    assert_eq!(document.kind, DocumentKind::Drawing);
    assert_eq!(document.pages.len(), 1);
}

#[test]
fn a_dangling_relationship_still_reads() {
    // A relationship to a missing part is recorded, not an error (P2-05).
    let bytes = common::build(Fixture::Malformed(Malformed::DanglingRelationship));
    let document = read_document(&bytes, &Limits::DEFAULT).expect("reads");
    assert_eq!(document.pages.len(), 1);
}

#[test]
fn malformed_packages_never_panic() {
    for malformed in [
        Malformed::TruncatedZip,
        Malformed::BadCentralDirectory,
        Malformed::BadContentTypes,
        Malformed::DeepNesting,
        Malformed::HugeDeclaredSize,
        Malformed::ManyEntries,
    ] {
        let bytes = common::build(Fixture::Malformed(malformed));
        let outcome = read_document(&bytes, &Limits::DEFAULT);
        // Whatever the outcome, it is a value: no panic, and an error says so.
        if let Err(error) = outcome {
            let _ = error.to_string();
        }
    }
}

#[test]
fn read_document_composes_read_package_and_to_model() {
    let bytes = common::build(Fixture::Drawing);
    let package = read_package(&bytes, &Limits::DEFAULT).expect("package");
    let from_parts = to_model(&package).expect("document");
    let from_bytes = read_document(&bytes, &Limits::DEFAULT).expect("document");
    assert_eq!(from_parts, from_bytes);
}
